    openaiChatCompletions: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description auto, profile:<id>, sai:<slug>, or a model id */
                    model: string;
                    messages: {
                        role?: string;
                        content?: string;
                    }[];
                    stream?: boolean;
                    /** @description For the answer; 0 gives the same most likely answer every time. Left out, the model's default. */
                    temperature?: number;
                    /** @description The most tokens each answer-writing call may use. Left out, the model's default. */
                    max_tokens?: number;
                    /** @description OpenAI's newer name for max_tokens; wins when both are sent. */
                    max_completion_tokens?: number;
                    /** @description Known values: `low`, `medium`, `high`; others may be added. */
                    reasoning_effort?: string;
                    /** @description A reasoning model's thinking as reasoning_content, on the message or as stream deltas before the answer (#701, contract 1.43). Off by default. */
                    include_reasoning?: boolean;
                    response_format?: {
                        /** @description Known values: `text`, `json_object`, `json_schema`; others may be added. */
                        type?: string;
                        json_schema?: {
                            name?: string;
                            schema?: {
                                [key: string]: unknown;
                            };
                        };
                    };
                    /** @description include_usage ends a stream with a chunk of no choices and the usage (contract 1.58) */
                    stream_options?: {
                        include_usage?: boolean;
                    };
                    toskar?: components["schemas"]["AssistantOptions"];
                    yggdrasil?: components["schemas"]["AssistantOptions"];
                };
            };
        };
        responses: {
            /** @description The completion, or with stream, OpenAI's server-sent events */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OpenAIChatCompletion"];
                    "text/event-stream": string;
                };
            };
            /** @description Invalid JSON, no user message, an invalid response_format, or a picture Toskar can't use (INVALID_IMAGE) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OpenAIError"];
                };
            };
            /** @description An API key is required */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OpenAIError"];
                };
            };
            /** @description The API key does not allow what was asked */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OpenAIError"];
                };
            };
            /** @description The answer did not fit response_format after repair and one retry */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OpenAIError"];
                };
            };
            /** @description The chat failed; the message says why */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OpenAIError"];
                };
            };
        };
    };
